 1	/* ============================================================
 2	   views/project-detail.js — Project Detail view
 3	   Sections 4b–4d of the MCP Server Dashboard SPA
 4	   Depends on: API, Router, marked, escapeHtml, formatDate,
 5	               statusBadge, showLoading, showError,
 6	               OrchestratorWidgets (js/orchestrator-widgets.js),
 7	               UI (components.js)
 8	   ============================================================ */
 9	
10	// Module-scoped log-preview cleanup registry.
11	// Each renderProjectDetail() call drains this array before creating new widgets.
12	var _pdLogPreviewCleanups = [];
13	
14	/* ----------------------------------------------------------
15	   4b. View: Plan Document
16	   ---------------------------------------------------------- */
17	function extractSynopsis(markdown) {
18	  var match = markdown.match(/## Summary\s*\n([\s\S]*?)(?=\n## |\n---|\s*$)/);
19	  return match ? match[1].trim() : null;
20	}
21	
22	async function renderPlan(app, repo, slug) {
23	  app.innerHTML = '<p class="loading">Loading plan\u2026</p>';
24	  try {
25	    var result = await API.getPlanDocument(repo, slug);
26	    var html = marked.parse(result.content);
27	    app.innerHTML =
28	      breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
29	      '<div class="plan-content">' + html + '</div>';
30	  } catch (err) {

256	    });
257	  }
258	
259	  toolbarEl.appendChild(resumeBtn);
260	}
261	
262	/* ----------------------------------------------------------
263	   4c-i. DOM Patch Functions
264	   Targeted compare-and-swap helpers for in-place DOM updates.
265	   Each function performs fresh DOM queries on every invocation —
266	   no element references are cached across poll cycles.
267	   All functions are no-ops when the target element is not found.
268	   ---------------------------------------------------------- */
269	
270	/**
271	 * Update the project status badge in the page header.
272	 * @param {string} newStatus - New WP status string (e.g. 'IN_PROGRESS', 'COMPLETE').
273	 */
274	function _patchProjectStatus(newStatus) {
275	  var container = document.getElementById('project-status-badge');
276	  if (!container) return;
277	  var newHtml = statusBadge(newStatus);
278	  if (container.innerHTML !== newHtml) {
279	    container.innerHTML = newHtml;
280	  }
281	}
282	
283	/**
284	 * Update a single WP row's status badge and pipeline track cells in-place.
285	 * Leaves the WP ID and assigned-to cells untouched.
286	 * @param {string} wpId             - Work package ID (e.g. 'WP-001').
287	 * @param {string} newStatus        - New WP status string.
288	 * @param {string} newPipelineTrack - New pipeline track HTML (from buildPipelineTrack).
289	 */
290	function _patchWpRow(wpId, newStatus, newPipelineTrack) {
291	  var row = document.querySelector('tr[data-wp-id="' + escapeHtml(wpId) + '"]');
292	  if (!row) return;
293	
294	  var statusCell = row.querySelector('.wp-status-cell');
295	  if (statusCell) {
296	    var newStatusHtml = statusBadge(newStatus);
297	    if (statusCell.innerHTML !== newStatusHtml) {
298	      statusCell.innerHTML = newStatusHtml;
299	    }
300	  }
301	
302	  var pipelineCell = row.querySelector('.wp-pipeline-track-cell');
303	  if (pipelineCell) {
304	    if (pipelineCell.innerHTML !== newPipelineTrack) {
305	      pipelineCell.innerHTML = newPipelineTrack;
306	    }
307	  }
308	}
309	
310	/**
311	 * Show or hide the synthesis link row.
312	 * When visible=true and the row exists but is hidden, it is shown.
313	 * When visible=true and the row is absent, it is injected before the WP table.
314	 * When visible=false, the row is hidden.
315	 * @param {boolean} visible         - Whether the synthesis link should be visible.
316	 * @param {string}  [repo]          - Repository name (required when injecting).
317	 * @param {string}  [slug]          - Project slug (required when injecting).
318	 */
319	function _patchSynthesisLink(visible, repo, slug) {
320	  var row = document.getElementById('synthesis-link-row');
321	  if (visible) {
322	    if (row) {
323	      // Ensure the link href is populated if the row was pre-rendered empty.
324	      if (!row.querySelector('.synthesis-link') && repo && slug) {
325	        row.className = 'synthesis-link-row';
326	        row.innerHTML = '<a href="#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/synthesis" class="synthesis-link">View synthesis \u2192</a>';
327	      }
328	      row.style.display = '';
329	    } else if (repo && slug) {
330	      // Inject before the WP table section (card-title "Work Packages").
331	      var wpTitle = document.querySelector('.card-title');
332	      if (wpTitle) {
333	        var newRow = document.createElement('div');
334	        newRow.id = 'synthesis-link-row';
335	        newRow.className = 'synthesis-link-row';

336	        newRow.innerHTML = '<a href="#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/synthesis" class="synthesis-link">View synthesis \u2192</a>';
337	        wpTitle.parentNode.insertBefore(newRow, wpTitle);
338	      }
339	    }
340	  } else {
341	    if (row) {
342	      row.style.display = 'none';
343	    }
344	  }
345	}
346	
347	/**
348	 * Update the health badge text and CSS class.
349	 * @param {{ work_packages_needing_reset: number }} health - Health data object.
350	 */
351	function _patchHealthBadge(health) {
352	  var badge = document.getElementById('health-badge');
353	  if (!badge) return;
354	  if (health.work_packages_needing_reset === 0) {
355	    var newText = '\u2713 All pipelines complete';
356	    var newClass = 'health-badge healthy';
357	    if (badge.textContent !== newText) badge.textContent = newText;
358	    if (badge.className !== newClass) badge.className = newClass;
359	  } else {
360	    var count = health.work_packages_needing_reset;
361	    var newText2 = '\u26a0 ' + count + ' WP' + (count === 1 ? '' : 's') + ' need attention';
362	    var newClass2 = 'health-badge attention';
363	    if (badge.textContent !== newText2) badge.textContent = newText2;
364	    if (badge.className !== newClass2) badge.className = newClass2;
365	  }
366	}
367	
368	/**
369	 * Update the timing info display in-place.
370	 * @param {{ project_elapsed_ms: number, total_active_ms: number, pipeline_runs: number }} timing
371	 */
372	function _patchTimingInfo(timing) {
373	  var container = document.getElementById('timing-info');
374	  if (!container) return;
375	  if (!timing) return;
376	
377	  var durationEl = document.getElementById('timing-duration');
378	  if (durationEl) {
379	    var newDuration = formatDuration(timing.project_elapsed_ms);
380	    if (durationEl.textContent !== newDuration) durationEl.textContent = newDuration;
381	  }
382	
383	  var activeEl = document.getElementById('timing-active');
384	  if (activeEl) {
385	    var newActive = formatDuration(timing.total_active_ms);
386	    if (activeEl.textContent !== newActive) activeEl.textContent = newActive;
387	  }
388	
389	  var runsEl = document.getElementById('timing-runs');
390	  if (runsEl) {
391	    var newRuns = String(timing.pipeline_runs);
392	    if (runsEl.textContent !== newRuns) runsEl.textContent = newRuns;
393	  }
394	}
395	
396	function renderProjectDetail(app, repo, slug) {
397	  // Drain log preview cleanup callbacks from the previous render.
